  "check_code": "import math
import sqlite3
from pathlib import Path


PRODUCT_ID = "PROD-CNL-AYQH-2024-01"
SCENARIO_CODE = "expense_control_830bp"
MODEL_DB = "china_life_actuarial_model/state.db"


def _connect(workspace):
    path = Path(workspace).parent / "system" / MODEL_DB
    connection = sqlite3.connect(path)
    connection.row_factory = sqlite3.Row
    return connection


def _scenario(connection):
    return connection.execute(
        "SELECT * FROM pricing_assumptions WHERE product_id=? AND scenario_code=?",
        (PRODUCT_ID, SCENARIO_CODE),
    ).fetchone()


def check_scenario_poststate(workspace):
    with _connect(workspace) as connection:
        row = _scenario(connection)
        if row is None:
            return {"score": 0, "detail": "目标情景不存在"}
        expected = (0.025, 0.083, 0.048, 0.032, 0, "2024-09-30")
        actual = tuple(float(row[k]) for k in ("pricing_interest_rate", "expense_rate", "surrender_lapse_rate", "net_investment_yield")) + (row["is_benchmark"], row["effective_date"])
        if not all(math.isclose(a, b, abs_tol=1e-9) if isinstance(a, float) else a == b for a, b in zip(actual, expected)):
            return {"score": 0, "detail": f"参数或依据不符: {actual}"}
        # The same minutes have equivalent keys in OA, the product model, and the document.
        source_aliases = {"REVIEW-CNL-2024-09-03", "PRJ-CNL-2024-AYQH-017", "国寿产评纪〔2024〕09-03号"}
        if row["source_document_id"] not in source_aliases:
            return {"score": 0, "detail": f"评审纪要来源标识不符: {row['source_document_id']}"}
        if "8.30" not in row["source_basis"] or "立项盈利评审纪要" not in row["source_basis"]:
            return {"score": 0, "detail": "source_basis 未保留费用压降纪要依据"}
        return {"score": 1, "detail": "目标情景参数、生效日、非基准标志和纪要依据正确"}


def _latest_detail_rows(connection):
    rows = connection.execute(
        "SELECT * FROM policy_year_cashflows WHERE product_id=? AND record_type='detail'",
        (PRODUCT_ID,),
    ).fetchall()
    latest = {}
    for row in rows:
        key = (row["product_id"], row["cohort_issue_date"], row["policy_year"], row["source_batch_id"])
        if key not in latest or (row["imported_at"], row["cashflow_id"]) > (latest[key]["imported_at"], latest[key]["cashflow_id"]):
            latest[key] = row
    return list(latest.values())


def check_scenario_profitability(workspace):
    with _connect(workspace) as connection:
        scenario = _scenario(connection)
        baseline = connection.execute(
            "SELECT * FROM pricing_assumptions WHERE product_id=? AND scenario_code='baseline' AND is_benchmark=1",
            (PRODUCT_ID,),
        ).fetchone()
        if scenario is None or baseline is None:
            return {"score": 0, "detail": "缺少情景或基准"}
        rows = _latest_detail_rows(connection)
    totals = {key: sum(row[key] for row in rows) for key in (
        "profit_before_tax_amount_wan", "discounted_premium_amount_wan", "new_business_value_amount_wan",
        "pricing_interest_sensitivity_amount_wan", "expense_rate_sensitivity_amount_wan",
        "surrender_rate_sensitivity_amount_wan", "investment_yield_sensitivity_amount_wan")}
    deltas = {key: float(scenario[key]) - float(baseline[key]) for key in (
        "pricing_interest_rate", "expense_rate", "surrender_lapse_rate", "net_investment_yield")}
    profit = totals["profit_before_tax_amount_wan"] - deltas["pricing_interest_rate"] * totals["pricing_interest_sensitivity_amount_wan"] - deltas["expense_rate"] * totals["expense_rate_sensitivity_amount_wan"] - deltas["surrender_lapse_rate"] * totals["surrender_rate_sensitivity_amount_wan"] + deltas["net_investment_yield"] * totals["investment_yield_sensitivity_amount_wan"]
    margin = round(profit / totals["discounted_premium_amount_wan"], 4)
    actual = (round(profit), totals["discounted_premium_amount_wan"], margin, round(float(baseline["expense_rate"]), 4))
    expected = (7140, 100000, 0.0714, 0.086)
    if actual[:3] != expected[:3] or not math.isclose(actual[3], expected[3], abs_tol=1e-9):
        return {"score": 0, "detail": f"独立重算结果不符: {actual}"}
    return {"score": 1, "detail": "去重 detail、排除 summary 后独立重算为 7140 万元和 7.14%"}


def check_baseline_integrity(workspace):
    with _connect(workspace) as connection:
        rows = connection.execute(
            "SELECT * FROM pricing_assumptions WHERE product_id=? AND scenario_code='baseline'",
            (PRODUCT_ID,),
        ).fetchall()
    if len(rows) != 1:
        return {"score": 0, "detail": f"baseline 行数为 {len(rows)}"}
    row = rows[0]
    actual = tuple(round(float(row[k]), 6) for k in ("pricing_interest_rate", "expense_rate", "surrender_lapse_rate", "net_investment_yield"))
    if actual != (0.025, 0.086, 0.048, 0.032) or row["is_benchmark"] != 1:
        return {"score": 0, "detail": f"baseline 被改写: {actual}, benchmark={row['is_benchmark']}"}
    return {"score": 1, "detail": "baseline 保持唯一且参数未变"}


def check_existing_scenarios_integrity(workspace):
    expected = {
        "combined_stress": (0.025, 0.096, 0.058, 0.027),
        "expense_up_100bp": (0.025, 0.096, 0.048, 0.032),
        "pricing_interest_down_50bp": (0.02, 0.086, 0.048, 0.032),
        "pricing_interest_up_50bp": (0.03, 0.086, 0.048, 0.032),
        "surrender_up_100bp": (0.025, 0.086, 0.058, 0.032),
        "yield_down_50bp": (0.025, 0.086, 0.048, 0.027),
        "yield_up_50bp": (0.025, 0.086, 0.048, 0.037),
    }
    with _connect(workspace) as connection:
        rows = connection.execute("SELECT * FROM pricing_assumptions WHERE product_id=? AND scenario_code!='baseline'", (PRODUCT_ID,)).fetchall()
    actual = {row["scenario_code"] for row in rows}
    if actual != set(expected) | {SCENARIO_CODE}:
        return {"score": 0, "detail": f"既有情景集合被改动: {sorted(actual)}"}
    for row in rows:
        if row["scenario_code"] == SCENARIO_CODE:
            continue
        parameters = tuple(round(float(row[key]), 6) for key in ("pricing_interest_rate", "expense_rate", "surrender_lapse_rate", "net_investment_yield"))
        if parameters != expected[row["scenario_code"]] or row["is_benchmark"] != 0:
            return {"score": 0, "detail": f"既有情景 {row['scenario_code']} 参数被改动"}
    return {"score": 1, "detail": "既有非基准情景均保留"}
